/* Allocates a physical voice for a virtual voice. If the physical voice was stolen from another voice, queues a volume ramp and a stop on its filter so the old sound is cut off. Returns nonzero when a voice was allocated. */ s32 func_8010FE60(ALSynth *synth, ALVoice *voice, ALVoiceConfig *config)
{
    PVoice  *pvoice = 0;
    ALFilter *filter;
    ALParam *param;
    s32 stolen;



    voice->priority     = config->priority;
    voice->unityPitch   = config->unityPitch;
    voice->table        = 0;
    voice->fxBus        = config->fxBus;
    voice->state        = 0 ;
    voice->pvoice       = 0;

    stolen = func_8010FF90(synth, &pvoice, config->priority);

    if (pvoice) {     

        filter = pvoice->channelKnob;

        if (stolen) {

            pvoice->offset = 512;
            pvoice->vvoice->pvoice = 0;  



            param = __allocParam();
            param->delta      = synth->paramSamples;
            param->type       = AL_FILTER_SET_VOLUME;
            param->data.i     = 0;
            param->moredata.i = pvoice->offset - 64;
            (*filter->setParam)(filter, AL_FILTER_ADD_UPDATE, param);



            param = __allocParam();
            if (param) {
                param->delta  = synth->paramSamples + pvoice->offset;
                param->type   = AL_FILTER_STOP_VOICE;
                param->next   = 0;
                (*filter->setParam)(filter, AL_FILTER_ADD_UPDATE, param);
            } else {

            }

        } else {
            pvoice->offset = 0;
        }

        pvoice->vvoice = voice;      
        voice->pvoice  = pvoice;

    }

    return (pvoice != 0);
}

